/** Block variants that are the same target while mining (redstone ore lights up). */
export const VALIDITY_MAP = {
        "minecraft:redstone_ore": "minecraft:lit_redstone_ore",
        "minecraft:deepslate_redstone_ore": "minecraft:lit_deepslate_redstone_ore"
    };

/** Blocks a new block may be placed into (vegetation, fluids, fire). */
export const OVERRIDEABLE_BLOCKS = new Set(["minecraft:bubble_column", "minecraft:bush", "minecraft:crimson_fungus", "minecraft:crimson_roots", "minecraft:deadbush", "minecraft:fern", "minecraft:fire", "minecraft:flowing_lava", "minecraft:flowing_water", "minecraft:glow_lichen", "minecraft:large_fern", "minecraft:lava", "minecraft:leaf_litter", "minecraft:nether_sprouts", "minecraft:pink_petals", "minecraft:powder_snow", "minecraft:resin_clump", "minecraft:sculk_vein", "minecraft:short_dry_grass", "minecraft:short_grass", "minecraft:soul_fire", "minecraft:sweet_berry_bush", "minecraft:tall_dry_grass", "minecraft:tall_grass", "minecraft:twisting_vines", "minecraft:warped_fungus", "minecraft:warped_roots", "minecraft:water", "minecraft:weeping_vines"]);

/** Fold lit/unlit variants so a plan does not lose its target mid-dig. */
export function canonicalBlock(typeId) {
    return VALIDITY_MAP[typeId] ?? typeId;
}

export function isRestricted(typeId) {
    return RESTRICTED_BLOCKS.has(canonicalBlock(typeId));
}

export function isOverrideable(typeId) {
    return OVERRIDEABLE_BLOCKS.has(typeId);
}
